{
  "name": "IPTV Manager Pro",
  "description": "Sistema de gestão de clientes IPTV com lembretes automáticos de renovação e geração de mensagens via IA."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Client {
  id: string;
  name: string;
  phone: string;
  startDate: string; // ISO Date string
  renewalDate: string; // ISO Date string
  price: number;
  devices: number;
  notes?: string;
  server?: string;
}

export interface ClientStats {
  totalClients: number;
  activeRevenue: number;
  expiringSoon: number;
}

import { GoogleGenAI } from "@google/genai";
import { Client } from "../types";

// Initialize Gemini
// NOTE: process.env.API_KEY is expected to be available in the build environment
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateRenewalMessage = async (client: Client): Promise<string> => {
  if (!process.env.API_KEY) {
    return "Erro: Chave de API não configurada. Por favor, configure a variável de ambiente API_KEY.";
  }

  try {
    const formattedDate = new Date(client.renewalDate).toLocaleDateString('pt-BR');

    const prompt = `
      Crie uma mensagem curta, amigável e profissional para WhatsApp em Português do Brasil.

      Contexto: Sou um revendedor de IPTV e preciso cobrar a renovação do cliente.

      Dados do Cliente:
      - Nome: ${client.name}
      - Data de Vencimento: ${formattedDate}
      - Valor: R$ ${client.price.toFixed(2)}
      - Plano para ${client.devices} dispositivo(s).

      Instruções:
      1. A mensagem deve lembrar que o plano está próximo do vencimento ou venceu.
      2. Inclua uma chamada para ação (perguntar se deseja renovar ou enviar o pix).
      3. Use emojis para ficar visualmente agradável, mas não exagerado.
      4. Não coloque assunto, apenas o corpo da mensagem.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "Não foi possível gerar a mensagem.";
  } catch (error) {
    console.error("Error generating message:", error);
    return "Ocorreu um erro ao conectar com a IA para gerar a mensagem.";
  }
};

