        <div className="p-3 bg-blue-500/10 rounded-xl text-blue-500">
          <Users size={24} />
        </div>
        <div>
          <p className="text-slate-400 text-sm font-medium">Total de Clientes</p>
          <h3 className="text-2xl font-bold text-white">{stats.totalClients}</h3>
        </div>
      </div>

      <div className="bg-slate-900 border border-slate-800 p-6 rounded-2xl shadow-lg flex items-center gap-4">
        <div className="p-3 bg-green-500/10 rounded-xl text-green-500">
          <DollarSign size={24} />
        </div>
        <div>
          <p className="text-slate-400 text-sm font-medium">Receita Mensal</p>
          <h3 className="text-2xl font-bold text-white">R$ {stats.activeRevenue.toFixed(2)}</h3>
        </div>
      </div>

      <div className="bg-slate-900 border border-slate-800 p-6 rounded-2xl shadow-lg flex items-center gap-4">
        <div className="p-3 bg-orange-500/10 rounded-xl text-orange-500">
          <AlertTriangle size={24} />
        </div>
        <div>
          <p className="text-slate-400 text-sm font-medium">Vencem em 3 dias</p>
