import React, { useState } from 'react';
import { Client } from '../types';
import { Calendar, Smartphone, DollarSign, MessageCircle, Trash2, Edit, Wand2, Copy, Check } from 'lucide-react';
import { generateRenewalMessage } from '../services/geminiService';

interface ClientCardProps {
  client: Client;
  daysUntilExpiration: number;
  onDelete: (id: string) => void;
  onEdit: (client: Client) => void;
}

export const ClientCard: React.FC<ClientCardProps> = ({ client, daysUntilExpiration, onDelete, onEdit }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedMsg, setGeneratedMsg] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  // Status Logic
  let statusColor = "border-slate-800 bg-slate-900";
  let badgeColor = "bg-slate-800 text-slate-300";
  let statusText = "Ativo";

  if (daysUntilExpiration < 0) {
    statusColor = "border-red-900/50 bg-red-950/20";
    badgeColor = "bg-red-900/50 text-red-200";
    statusText = `Venceu há ${Math.abs(daysUntilExpiration)} dias`;
  } else if (daysUntilExpiration <= 3) {
    statusColor = "border-orange-900/50 bg-orange-950/20";
    badgeColor = "bg-orange-900/50 text-orange-200";
    statusText = daysUntilExpiration === 0 ? "Vence Hoje" : `Vence em ${daysUntilExpiration} dias`;
  }

  const handleGenerateMessage = async () => {
    setIsGenerating(true);
    setGeneratedMsg(null);
    const msg = await generateRenewalMessage(client);
    setGeneratedMsg(msg);
    setIsGenerating(false);
  };

  const copyToClipboard = () => {
    if (generatedMsg) {
      navigator.clipboard.writeText(generatedMsg);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const sendWhatsApp = () => {
    if (!client.phone) return;
    // Clean phone number
    const cleanPhone = client.phone.replace(/\D/g, '');
    const text = generatedMsg ? encodeURIComponent(generatedMsg) : "";
    window.open(`https://wa.me/55${cleanPhone}?text=${text}`, '_blank');
  };

  return (
    <div className={`rounded-xl border p-5 transition-all hover:shadow-lg ${statusColor}`}>
      <div className="flex justify-between items-start mb-4">
        <div>
          <h3 className="text-xl font-bold text-white mb-1">{client.name}</h3>
          <span className={`text-xs px-2 py-1 rounded-full font-medium ${badgeColor}`}>
            {statusText}
          </span>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={() => onEdit(client)}
            className="p-2 text-slate-400 hover:text-blue-400 hover:bg-slate-800 rounded-lg transition-colors"
            title="Editar"
          >
            <Edit size={18} />
          </button>
          <button 
            onClick={() => onDelete(client.id)}
            className="p-2 text-slate-400 hover:text-red-400 hover:bg-slate-800 rounded-lg transition-colors"
            title="Excluir"
          >
            <Trash2 size={18} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 mb-4 text-sm text-slate-300">
        <div className="flex items-center gap-2">
          <Calendar size={16} className="text-slate-500" />
          <span>Renova: {new Date(client.renewalDate).toLocaleDateString('pt-BR')}</span>
        </div>
        <div className="flex items-center gap-2">
          <DollarSign size={16} className="text-slate-500" />
          <span>R$ {client.price.toFixed(2)}</span>
        </div>
        <div className="flex items-center gap-2">
          <Smartphone size={16} className="text-slate-500" />
          <span>{client.devices} Tela(s)</span>
        </div>
        {client.server && (
           <div className="flex items-center gap-2">
           <span className="text-slate-500 font-bold text-xs">SRV</span>
           <span>{client.server}</span>
         </div>
        )}
      </div>

      {/* Message Generator Section */}
      <div className="mt-4 pt-4 border-t border-slate-700/50">
        {!generatedMsg ? (
           <div className="flex gap-2">
             <button
              onClick={handleGenerateMessage}
              disabled={isGenerating}
              className="flex-1 bg-purple-600 hover:bg-purple-700 text-white py-2 px-4 rounded-lg flex items-center justify-center gap-2 text-sm font-medium transition-colors disabled:opacity-50"
             >
               {isGenerating ? (
                 <span className="animate-pulse">Criando...</span>
               ) : (
                 <>
                   <Wand2 size={16} />
                   Gerar Cobrança IA
                 </>
               )}
             </button>
             {/* Direct simple whatsapp button without AI text first */}
              <button 
                onClick={() => {
                  const cleanPhone = client.phone.replace(/\D/g, '');
                  window.open(`https://wa.me/55${cleanPhone}`, '_blank');
                }}
                className="bg-green-600 hover:bg-green-700 text-white p-2 rounded-lg"
                title="WhatsApp Direto"
              >
                <MessageCircle size={20} />
              </button>
           </div>
        ) : (
          <div className="bg-slate-800 rounded-lg p-3 animate-in fade-in slide-in-from-top-2">
            <p className="text-slate-300 text-sm whitespace-pre-line mb-3 border-l-2 border-purple-500 pl-3">
              {generatedMsg}
            </p>
            <div className="flex gap-2">
              <button
                onClick={copyToClipboard}
                className="flex-1 bg-slate-700 hover:bg-slate-600 text-white py-1.5 rounded flex items-center justify-center gap-2 text-xs transition-colors"
              >
                {copied ? <Check size={14} /> : <Copy size={14} />}
                {copied ? "Copiado!" : "Copiar"}
              </button>
              <button
                onClick={sendWhatsApp}
                className="flex-1 bg-green-600 hover:bg-green-700 text-white py-1.5 rounded flex items-center justify-center gap-2 text-xs transition-colors"
              >
                <MessageCircle size={14} />
                Enviar WhatsApp
              </button>
              <button 
                 onClick={() => setGeneratedMsg(null)}
                 className="px-3 py-1 text-slate-400 hover:text-white text-xs"
              >
                Fechar
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Client } from '../types';
import { X, Save } from 'lucide-react';

interface ClientModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  editingClient: Client | null;
}

const emptyClient: Omit<Client, 'id'> = {
  name: '',
  phone: '',
  startDate: new Date().toISOString().split('T')[0],
  renewalDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
  price: 35.00,
  devices: 1,
  notes: '',
  server: ''
};

export const ClientModal: React.FC<ClientModalProps> = ({ isOpen, onClose, onSave, editingClient }) => {
  const [formData, setFormData] = useState<Omit<Client, 'id'>>(emptyClient);

  useEffect(() => {
    if (editingClient) {
      setFormData({
        name: editingClient.name,
        phone: editingClient.phone,
        startDate: editingClient.startDate.split('T')[0],
        renewalDate: editingClient.renewalDate.split('T')[0],
        price: editingClient.price,
        devices: editingClient.devices,
        notes: editingClient.notes || '',
        server: editingClient.server || ''
      });
    } else {
      setFormData(emptyClient);
    }
  }, [editingClient, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      id: editingClient ? editingClient.id : crypto.randomUUID(),
    });
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl w-full max-w-lg shadow-2xl overflow-hidden">
        <div className="p-6 border-b border-slate-800 flex justify-between items-center bg-slate-900">
          <h2 className="text-xl font-bold text-white">
            {editingClient ? 'Editar Cliente' : 'Novo Cliente'}
          </h2>
          <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
            <X size={24} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4 max-h-[80vh] overflow-y-auto">
          <div>
            <label className="block text-sm font-medium text-slate-400 mb-1">Nome Completo</label>
            <input
              type="text"
              required
              value={formData.name}
              onChange={e => setFormData({...formData, name: e.target.value})}
              className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 focus:border-transparent outline-none transition-all"
              placeholder="Ex: João da Silva"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-400 mb-1">WhatsApp / Telefone</label>
            <input
              type="tel"
              required
              value={formData.phone}
              onChange={e => setFormData({...formData, phone: e.target.value})}
              className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 focus:border-transparent outline-none transition-all"
              placeholder="Ex: 11999998888"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-400 mb-1">Início</label>
              <input
                type="date"
                required
                value={formData.startDate}
                onChange={e => setFormData({...formData, startDate: e.target.value})}
                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-400 mb-1">Renovação</label>
              <input
                type="date"
                required
                value={formData.renewalDate}
                onChange={e => setFormData({...formData, renewalDate: e.target.value})}
                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 outline-none"
              />
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div className="col-span-1">
              <label className="block text-sm font-medium text-slate-400 mb-1">Preço (R$)</label>
              <input
                type="number"
                step="0.01"
                required
                value={formData.price}
                onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})}
                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 outline-none"
              />
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-medium text-slate-400 mb-1">Telas</label>
              <input
                type="number"
                min="1"
                required
                value={formData.devices}
                onChange={e => setFormData({...formData, devices: parseInt(e.target.value)})}
                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 outline-none"
              />
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-medium text-slate-400 mb-1">Servidor</label>
              <input
                type="text"
                value={formData.server}
                onChange={e => setFormData({...formData, server: e.target.value})}
                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                placeholder="Ex: P2P"
              />
            </div>
          </div>

          <div className="pt-4 flex justify-end gap-3">
             <button
              type="button"
              onClick={onClose}
              className="px-4 py-2.5 rounded-lg text-slate-300 hover:bg-slate-800 transition-colors font-medium"
            >
              Cancelar
            </button>
            <button
              type="submit"
              className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-lg font-medium flex items-center gap-2 transition-colors shadow-lg shadow-blue-900/20"
            >
              <Save size={18} />
              Salvar Cliente
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Client, ClientStats } from './types';
import { Plus, Search, Tv } from 'lucide-react';
import { StatsCards } from './components/StatsCards';
import { ClientCard } from './components/ClientCard';
import { ClientModal } from './components/ClientModal';

// Storage Key
const STORAGE_KEY = 'iptv_manager_clients_v1';

// Helper to calculate days difference
const getDaysDifference = (dateString: string): number => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const targetDate = new Date(dateString);
  targetDate.setHours(0, 0, 0, 0);
  const diffTime = targetDate.getTime() - today.getTime();
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const App: React.FC = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);

  // Load from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        setClients(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse clients", e);
      }
    }
  }, []);

  // Save to local storage whenever clients change
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(clients));
  }, [clients]);

  // Derived Statistics
  const stats: ClientStats = useMemo(() => {
    let revenue = 0;
    let expiring = 0;

    clients.forEach(c => {
      revenue += c.price;
      const days = getDaysDifference(c.renewalDate);
      if (days <= 3) expiring++;
    });

    return {
      totalClients: clients.length,
      activeRevenue: revenue,
      expiringSoon: expiring
    };
  }, [clients]);

  // Filter and Sort Clients
  // Priority: Expired/Expiring Soon -> Alphabetical
  const filteredClients = useMemo(() => {
    return clients
      .filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                   c.server?.toLowerCase().includes(searchTerm.toLowerCase()))
      .sort((a, b) => {
        const daysA = getDaysDifference(a.renewalDate);
        const daysB = getDaysDifference(b.renewalDate);

        // If both are expiring soon (<= 3 days), sort by date ascending (closest to expire first)
        if (daysA <= 3 && daysB <= 3) return daysA - daysB;

        // If only A is expiring soon, it goes first
        if (daysA <= 3) return -1;
        // If only B is expiring soon, it goes first
        if (daysB <= 3) return 1;

        // Otherwise sort by name
        return a.name.localeCompare(b.name);
      });
  }, [clients, searchTerm]);

  // Handlers
  const handleAddClient = () => {
    setEditingClient(null);
    setIsModalOpen(true);
  };

  const handleEditClient = (client: Client) => {
    setEditingClient(client);
    setIsModalOpen(true);
  };

  const handleSaveClient = (client: Client) => {
    if (editingClient) {
      setClients(prev => prev.map(c => c.id === client.id ? client : c));
    } else {
      setClients(prev => [...prev, client]);
    }
  };

  const handleDeleteClient = (id: string) => {
    if (confirm('Tem certeza que deseja remover este cliente?')) {
      setClients(prev => prev.filter(c => c.id !== id));
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 pb-20">
      {/* Header */}
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg">
              <Tv className="text-white" size={24} />
            </div>
            <h1 className="text-xl font-bold text-white tracking-tight">IPTV Manager Pro</h1>
          </div>
          <button 
            onClick={handleAddClient}
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition-colors shadow-lg shadow-blue-900/20"
          >
            <Plus size={18} />
            <span className="hidden sm:inline">Novo Cliente</span>
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        <StatsCards stats={stats} />

        {/* Search Bar */}
        <div className="mb-6 relative">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search className="text-slate-500" size={20} />
          </div>
          <input
            type="text"
            placeholder="Buscar por nome ou servidor..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-slate-900 border border-slate-800 text-white rounded-xl pl-10 pr-4 py-3 focus:ring-2 focus:ring-blue-600 focus:border-transparent outline-none transition-all placeholder-slate-500"
          />
        </div>

        {/* Grid List */}
        {filteredClients.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredClients.map(client => (
              <ClientCard 
                key={client.id} 
                client={client}
                daysUntilExpiration={getDaysDifference(client.renewalDate)}
                onDelete={handleDeleteClient}
                onEdit={handleEditClient}
              />
            ))}
          </div>
        ) : (
          <div className="text-center py-20 bg-slate-900/50 rounded-2xl border border-slate-800 border-dashed">
            <div className="bg-slate-800 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
              <Plus size={32} className="text-slate-500" />
            </div>
            <h3 className="text-lg font-medium text-white mb-2">Nenhum cliente encontrado</h3>
            <p className="text-slate-500 max-w-sm mx-auto">
              Comece adicionando seus clientes de IPTV para gerenciar renovações e gerar mensagens automáticas.
            </p>
            <button 
              onClick={handleAddClient}
              className="mt-6 text-blue-400 hover:text-blue-300 font-medium"
            >
              Adicionar primeiro cliente
            </button>
          </div>
        )}
      </main>

      <ClientModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveClient}
        editingClient={editingClient}
      />
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { Client } from "../types";

// Initialize Gemini
// NOTE: process.env.API_KEY is expected to be available in the build environment
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateRenewalMessage = async (client: Client): Promise<string> => {
  if (!process.env.API_KEY) {
    return "Erro: Chave de API não configurada. Por favor, configure a variável de ambiente API_KEY.";
  }

  try {
    const formattedDate = new Date(client.renewalDate).toLocaleDateString('pt-BR');

    const prompt = `
      Atue como um assistente pessoal de um revendedor de IPTV.
      Escreva uma mensagem de cobrança/renovação para WhatsApp (PT-BR) para o cliente abaixo.

      Dados do Cliente:
      - Nome: ${client.name}
      - Vencimento: ${formattedDate}
      - Valor: R$ ${client.price.toFixed(2)}
      - Telas: ${client.devices}

      REGRAS ESTRITAS PARA A MENSAGEM:
      1. Informe educadamente que o plano está próximo do vencimento ou venceu.
      2. Informe OBRIGATORIAMENTE a Chave Pix para pagamento: 55996138553
      3. Adicione explicitamente a frase: "Assim que recebermos o pagamento/comprovante, sua renovação será feita imediatamente!"
      4. Use emojis relacionados a TV, Filmes e Pagamento para tornar a mensagem agradável.
      5. Seja breve e direto, retorne apenas o texto da mensagem pronto para copiar e enviar.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "Não foi possível gerar a mensagem.";
  } catch (error) {
    console.error("Error generating message:", error);
    return "Ocorreu um erro ao conectar com a IA para gerar a mensagem.";
  }
};

import React, { useState } from 'react';
import { Client } from '../types';
import { Calendar, Smartphone, DollarSign, MessageCircle, Trash2, Edit, Wand2, Copy, Check, UserCheck, Clock, AlertCircle } from 'lucide-react';
import { generateRenewalMessage } from '../services/geminiService';

interface ClientCardProps {
  client: Client;
  daysUntilExpiration: number;
  onDelete: (id: string) => void;
  onEdit: (client: Client) => void;
}

export const ClientCard: React.FC<ClientCardProps> = ({ client, daysUntilExpiration, onDelete, onEdit }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedMsg, setGeneratedMsg] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  // Status Logic
  // Default: Active (Green)
  let statusColor = "border-green-500/30 bg-green-500/5 hover:shadow-green-900/20 hover:border-green-500/50";
  let badgeColor = "bg-green-500/10 text-green-400 border border-green-500/20";
  let iconColor = "text-green-500";
  let statusText = "Ativo";
  let StatusIcon = UserCheck;

  if (daysUntilExpiration < 0) {
    // Expired (Red)
    statusColor = "border-red-500/30 bg-red-500/5 hover:shadow-red-900/20 hover:border-red-500/50";
    badgeColor = "bg-red-500/10 text-red-400 border border-red-500/20";
    iconColor = "text-red-500";
    statusText = "Vencido";
    StatusIcon = AlertCircle;
  } else if (daysUntilExpiration <= 3) {
    // Expiring Soon (Orange)
    statusColor = "border-orange-500/30 bg-orange-500/5 hover:shadow-orange-900/20 hover:border-orange-500/50";
    badgeColor = "bg-orange-500/10 text-orange-400 border border-orange-500/20";
    iconColor = "text-orange-400";
    statusText = "Vencendo";
    StatusIcon = Clock;
  }

  const handleGenerateMessage = async () => {
    setIsGenerating(true);
    setGeneratedMsg(null);
    const msg = await generateRenewalMessage(client);
    setGeneratedMsg(msg);
    setIsGenerating(false);
  };

  const copyToClipboard = () => {
    if (generatedMsg) {
      navigator.clipboard.writeText(generatedMsg);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const sendWhatsApp = () => {
    if (!client.phone) return;
    // Clean phone number
    const cleanPhone = client.phone.replace(/\D/g, '');
    const text = generatedMsg ? encodeURIComponent(generatedMsg) : "";
    window.open(`https://wa.me/55${cleanPhone}?text=${text}`, '_blank');
  };

  return (
    <div className={`rounded-xl border p-5 transition-all hover:shadow-lg ${statusColor}`}>
      <div className="flex justify-between items-start mb-4">
        <div className="flex gap-3">
          <div className={`mt-1 p-2 rounded-lg bg-slate-900/80 border border-slate-700/50 ${iconColor}`}>
            <StatusIcon size={24} />
          </div>
          <div>
            <h3 className="text-xl font-bold text-white mb-1">{client.name}</h3>
            <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${badgeColor}`}>
              {statusText}
            </span>
          </div>
        </div>

        <div className="flex gap-2">
          <button 
            onClick={() => onEdit(client)}
            className="p-2 text-slate-400 hover:text-blue-400 hover:bg-slate-800 rounded-lg transition-colors"
            title="Editar"
          >
            <Edit size={18} />
          </button>
          <button 
            onClick={() => onDelete(client.id)}
            className="p-2 text-slate-400 hover:text-red-400 hover:bg-slate-800 rounded-lg transition-colors"
            title="Excluir"
          >
            <Trash2 size={18} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 mb-4 text-sm text-slate-300">
        <div className="flex items-center gap-2">
          <Calendar size={16} className="text-slate-500" />
          <span>Renova: {new Date(client.renewalDate).toLocaleDateString('pt-BR')}</span>
        </div>
        <div className="flex items-center gap-2">
          <DollarSign size={16} className="text-slate-500" />
          <span>R$ {client.price.toFixed(2)}</span>
        </div>
        <div className="flex items-center gap-2">
          <Smartphone size={16} className="text-slate-500" />
          <span>{client.devices} Tela(s)</span>
        </div>
        {client.server && (
           <div className="flex items-center gap-2">
           <span className="text-slate-500 font-bold text-xs">SRV</span>
           <span>{client.server}</span>
         </div>
        )}
      </div>

      {/* Message Generator Section */}
      <div className="mt-4 pt-4 border-t border-slate-700/50">
        {!generatedMsg ? (
           <div className="flex gap-2">
             <button
              onClick={handleGenerateMessage}
              disabled={isGenerating}
              className="flex-1 bg-purple-600 hover:bg-purple-700 text-white py-2 px-4 rounded-lg flex items-center justify-center gap-2 text-sm font-medium transition-colors disabled:opacity-50"
             >
               {isGenerating ? (
                 <span className="animate-pulse">Criando...</span>
               ) : (
                 <>
                   <Wand2 size={16} />
                   Gerar Cobrança IA
                 </>
               )}
             </button>
             {/* Direct simple whatsapp button without AI text first */}
              <button 
                onClick={() => {
                  const cleanPhone = client.phone.replace(/\D/g, '');
                  window.open(`https://wa.me/55${cleanPhone}`, '_blank');
                }}
                className="bg-green-600 hover:bg-green-700 text-white p-2 rounded-lg"
                title="WhatsApp Direto"
              >
                <MessageCircle size={20} />
              </button>
           </div>
        ) : (
          <div className="bg-slate-800 rounded-lg p-3 animate-in fade-in slide-in-from-top-2">
            <p className="text-slate-300 text-sm whitespace-pre-line mb-3 border-l-2 border-purple-500 pl-3">
              {generatedMsg}
            </p>
            <div className="flex gap-2">
              <button
                onClick={copyToClipboard}
                className="flex-1 bg-slate-700 hover:bg-slate-600 text-white py-1.5 rounded flex items-center justify-center gap-2 text-xs transition-colors"
              >
                {copied ? <Check size={14} /> : <Copy size={14} />}
                {copied ? "Copiado!" : "Copiar"}
              </button>
              <button
                onClick={sendWhatsApp}
                className="flex-1 bg-green-600 hover:bg-green-700 text-white py-1.5 rounded flex items-center justify-center gap-2 text-xs transition-colors"
              >
                <MessageCircle size={14} />
                Enviar WhatsApp
              </button>
              <button 
                 onClick={() => setGeneratedMsg(null)}
                 className="px-3 py-1 text-slate-400 hover:text-white text-xs"
              >
                Fechar
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell, BarChart, Bar, Legend 
} from 'recharts';
import { Client } from '../types';
import { TrendingUp, Users, DollarSign, Activity } from 'lucide-react';

interface AnalyticsViewProps {
  clients: Client[];
}

export const AnalyticsView: React.FC<AnalyticsViewProps> = ({ clients }) => {
  // 1. Receita por Mês (Baseado na Data de Início)
  const revenueByMonth = clients.reduce((acc: any[], client) => {
    const date = new Date(client.startDate);
    const monthYear = date.toLocaleDateString('pt-BR', { month: 'short', year: '2-digit' });

    const existing = acc.find(item => item.name === monthYear);
    if (existing) {
      existing.receita += client.price;
      existing.clientes += 1;
    } else {
      acc.push({ name: monthYear, receita: client.price, clientes: 1, sortDate: date.getTime() });
    }
    return acc;
  }, []).sort((a, b) => a.sortDate - b.sortDate);

  // 2. Distribuição por Status
  const today = new Date();
  today.setHours(0,0,0,0);

  const statusData = [
    { name: 'Ativos', value: 0, color: '#22c55e' },
    { name: 'Vencendo', value: 0, color: '#fb923c' },
    { name: 'Vencidos', value: 0, color: '#ef4444' },
  ];

  clients.forEach(c => {
    const renDate = new Date(c.renewalDate);
    const diff = Math.ceil((renDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));

    if (diff < 0) statusData[2].value++;
    else if (diff <= 3) statusData[1].value++;
    else statusData[0].value++;
  });

  // 3. Clientes por Servidor
  const serverData = clients.reduce((acc: any[], client) => {
    const srv = client.server || 'Outros';
    const existing = acc.find(item => item.name === srv);
    if (existing) existing.total++;
    else acc.push({ name: srv, total: 1 });
    return acc;
  }, []).sort((a, b) => b.total - a.total).slice(0, 5);

  const totalRevenue = clients.reduce((sum, c) => sum + c.price, 0);
  const avgTicket = clients.length > 0 ? totalRevenue / clients.length : 0;

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Mini Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatCard title="Total Acumulado" value={`R$ ${totalRevenue.toFixed(2)}`} icon={<TrendingUp size={20}/>} color="blue" />
        <StatCard title="Ticket Médio" value={`R$ ${avgTicket.toFixed(2)}`} icon={<DollarSign size={20}/>} color="emerald" />
        <StatCard title="Novos Clientes" value={clients.length.toString()} icon={<Users size={20}/>} color="purple" />
        <StatCard title="Saúde Financeira" value="94%" icon={<Activity size={20}/>} color="amber" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Gráfico de Evolução da Receita */}
        <div className="bg-slate-900 border border-slate-800 p-6 rounded-2xl shadow-xl">
          <h3 className="text-lg font-bold text-white mb-6">Evolução da Receita (R$)</h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={revenueByMonth}>
                <defs>
                  <linearGradient id="colorRec" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} />
                <YAxis stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} tickFormatter={(val) => `R$${val}`} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '8px' }}
                  itemStyle={{ color: '#fff' }}
                />
                <Area type="monotone" dataKey="receita" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorRec)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Gráfico de Distribuição de Status */}
        <div className="bg-slate-900 border border-slate-800 p-6 rounded-2xl shadow-xl">
          <h3 className="text-lg font-bold text-white mb-6">Status da Base</h3>
          <div className="h-[300px] w-full flex items-center justify-center">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={statusData.filter(d => d.value > 0)}
                  cx="50%"
                  cy="50%"
                  innerRadius={80}
                  outerRadius={100}
                  paddingAngle={8}
                  dataKey="value"
                >
                  {statusData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip 
                   contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '8px' }}
                />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Servidores mais usados */}
      <div className="bg-slate-900 border border-slate-800 p-6 rounded-2xl shadow-xl">
        <h3 className="text-lg font-bold text-white mb-6">Top 5 Servidores</h3>
        <div className="h-[250px] w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={serverData} layout="vertical">
              <CartesianGrid strokeDasharray="3 3" horizontal={false} />
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" stroke="#fff" fontSize={12} width={100} />
              <Tooltip cursor={{fill: '#1e293b'}} contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b' }} />
              <Bar dataKey="total" fill="#8b5cf6" radius={[0, 4, 4, 0]} barSize={20} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ title, value, icon, color }: { title: string, value: string, icon: any, color: string }) => {
