import React, { useState, useEffect, useMemo } from 'react';
import { Client, ClientStats } from './types';
import { Plus, Search, Tv, Users, LayoutDashboard, BarChart3 } from 'lucide-react';
import { StatsCards } from './components/StatsCards';
import { ClientCard } from './components/ClientCard';
import { ClientModal } from './components/ClientModal';
import { AnalyticsView } from './components/AnalyticsView';

// Storage Key
const STORAGE_KEY = 'iptv_manager_clients_v1';

// Helper to calculate days difference
const getDaysDifference = (dateString: string): number => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const targetDate = new Date(dateString);
  targetDate.setHours(0, 0, 0, 0);
  const diffTime = targetDate.getTime() - today.getTime();
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const App: React.FC = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);
  const [activeTab, setActiveTab] = useState<'list' | 'analytics'>('list');

  // Load from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        setClients(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse clients", e);
      }
    }
  }, []);

  // Save to local storage whenever clients change
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(clients));
  }, [clients]);

  // Derived Statistics
  const stats: ClientStats = useMemo(() => {
    let revenue = 0;
    let expiring = 0;

    clients.forEach(c => {
      revenue += c.price;
      const days = getDaysDifference(c.renewalDate);
      if (days <= 3) expiring++;
    });

    return {
      totalClients: clients.length,
      activeRevenue: revenue,
      expiringSoon: expiring
    };
  }, [clients]);

  // Filter and Sort Clients
  const filteredClients = useMemo(() => {
    return clients
      .filter(c => c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                   c.server?.toLowerCase().includes(searchTerm.toLowerCase()))
      .sort((a, b) => {
        const daysA = getDaysDifference(a.renewalDate);
        const daysB = getDaysDifference(b.renewalDate);
        if (daysA <= 3 && daysB <= 3) return daysA - daysB;
        if (daysA <= 3) return -1;
        if (daysB <= 3) return 1;
        return a.name.localeCompare(b.name);
      });
  }, [clients, searchTerm]);

  // Handlers
  const handleAddClient = () => {
    setEditingClient(null);
    setIsModalOpen(true);
  };

  const handleEditClient = (client: Client) => {
    setEditingClient(client);
    setIsModalOpen(true);
  };

  const handleSaveClient = (client: Client) => {
    if (editingClient) {
      setClients(prev => prev.map(c => c.id === client.id ? client : c));
    } else {
      setClients(prev => [...prev, client]);
    }
  };

  const handleDeleteClient = (id: string) => {
    if (confirm('Tem certeza que deseja remover este cliente?')) {
      setClients(prev => prev.filter(c => c.id !== id));
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 pb-20">
      {/* Header */}
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-900/40">
              <Tv className="text-white" size={24} />
            </div>
            <h1 className="text-xl font-bold text-white tracking-tight">IPTV Manager Pro</h1>
          </div>
          <button 
            onClick={handleAddClient}
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition-all active:scale-95 shadow-lg shadow-blue-900/20"
          >
            <Plus size={18} />
            <span className="hidden sm:inline">Novo Cliente</span>
          </button>
        </div>

        {/* Tab Navigation */}
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex border-t border-slate-800/50">
          <button
            onClick={() => setActiveTab('list')}
            className={`flex items-center gap-2 px-6 py-3 text-sm font-semibold transition-all border-b-2 ${
              activeTab === 'list' 
              ? 'border-blue-500 text-blue-400 bg-blue-500/5' 
              : 'border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-800/30'
            }`}
          >
            <LayoutDashboard size={18} />
            Clientes
          </button>
          <button
            onClick={() => setActiveTab('analytics')}
            className={`flex items-center gap-2 px-6 py-3 text-sm font-semibold transition-all border-b-2 ${
              activeTab === 'analytics' 
              ? 'border-blue-500 text-blue-400 bg-blue-500/5' 
              : 'border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-800/30'
            }`}
          >
            <BarChart3 size={18} />
            Análise e Gráficos
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {activeTab === 'list' ? (
          <>
            <StatsCards stats={stats} />

            {/* Search Bar */}
            <div className="mb-6 relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Search className="text-slate-500" size={20} />
              </div>
              <input
                type="text"
                placeholder="Buscar por nome ou servidor..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-slate-900 border border-slate-800 text-white rounded-xl pl-10 pr-4 py-3 focus:ring-2 focus:ring-blue-600 focus:border-transparent outline-none transition-all placeholder-slate-500"
              />
            </div>

            {/* Grid List */}
            {filteredClients.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in slide-in-from-bottom-4 duration-500">
                {filteredClients.map(client => (
                  <ClientCard 
                    key={client.id} 
                    client={client}
                    daysUntilExpiration={getDaysDifference(client.renewalDate)}
                    onDelete={handleDeleteClient}
                    onEdit={handleEditClient}
                  />
                ))}
              </div>
            ) : (
              <div className="text-center py-20 bg-slate-900/50 rounded-2xl border border-slate-800 border-dashed">
                <div className="bg-slate-800 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                  <Plus size={32} className="text-slate-500" />
                </div>
                <h3 className="text-lg font-medium text-white mb-2">Nenhum cliente encontrado</h3>
                <p className="text-slate-500 max-w-sm mx-auto">
                  Adicione seus clientes para começar a gerenciar sua receita e renovações.
                </p>
                <button 
                  onClick={handleAddClient}
                  className="mt-6 text-blue-400 hover:text-blue-300 font-medium"
                >
                  Adicionar primeiro cliente
                </button>
              </div>
            )}
          </>
        ) : (
          <AnalyticsView clients={clients} />
        )}
      </main>

      <ClientModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveClient}
        editingClient={editingClient}
      />
    </div>
  );
};

export default App;

