    return users ? JSON.parse(users) : [];
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    const users = getUsers();

    if (isLogin) {
      const user = users.find(u => u.username === username && u.password === password);
      if (user) {
        onLogin({ id: user.id, username: user.username });
      } else {
        setError('Usuário ou senha incorretos.');
      }
    } else {
      if (users.find(u => u.username === username)) {
        setError('Este nome de usuário já está em uso.');
        return;
      }
      const newUser: UserType = {
        id: crypto.randomUUID(),
        username,
        password
      };
      localStorage.setItem('iptv_users_registry', JSON.stringify([...users, newUser]));
      onLogin({ id: newUser.id, username: newUser.username });
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-blue-900/20 via-slate-950 to-slate-950">
