          <h1 className="text-3xl font-bold text-white tracking-tight">IPTV Manager Pro</h1>
          <p className="text-slate-400 mt-2">Sua gestão de clientes em um só lugar</p>
        </div>

        <div className="bg-slate-900/50 backdrop-blur-xl border border-slate-800 rounded-3xl p-8 shadow-2xl">
          <h2 className="text-xl font-semibold text-white mb-6 flex items-center gap-2">
            {isLogin ? <LogIn size={20} className="text-blue-500" /> : <UserPlus size={20} className="text-blue-500" />}
            {isLogin ? 'Acesse sua conta' : 'Crie sua conta'}
          </h2>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-400 mb-1.5 ml-1">Usuário</label>
              <div className="relative">
                <User className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
                <input
                  type="text"
                  required
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full bg-slate-950/50 border border-slate-800 rounded-xl pl-10 pr-4 py-3 text-white focus:ring-2 focus:ring-blue-600 outline-none transition-all"
                  placeholder="Seu usuário"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-400 mb-1.5 ml-1">Senha</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
                <input
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-slate-950/50 border border-slate-800 rounded-xl pl-10 pr-4 py-3 text-white focus:ring-2 focus:ring-blue-600 outline-none transition-all"
                  placeholder="••••••••"
                />
              </div>
            </div>

            {error && (
              <div className="bg-red-500/10 border border-red-500/20 text-red-500 text-sm py-2 px-3 rounded-lg text-center animate-shake">
                {error}
              </div>
            )}

            <button
              type="submit"
              className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold py-3 px-4 rounded-xl flex items-center justify-center gap-2 transition-all active:scale-95 shadow-lg shadow-blue-900/20 mt-6"
            >
              {isLogin ? 'Entrar no Painel' : 'Finalizar Cadastro'}
              <ArrowRight size={18} />
            </button>
          </form>

          <div className="mt-8 pt-6 border-t border-slate-800 text-center">
            <button
              onClick={() => { setIsLogin(!isLogin); setError(''); }}
              className="text-slate-400 hover:text-white text-sm transition-colors"
            >
              {isLogin ? 'Não tem uma conta? Cadastre-se' : 'Já possui conta? Faça login'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Client, ClientStats, User as UserType } from './types';
import { Plus, Search, Tv, Users, LayoutDashboard, BarChart3, CheckCircle2, Clock, AlertCircle, Filter, Bell, BellOff, LogOut, User as UserIcon } from 'lucide-react';
import { StatsCards } from './components/StatsCards';
import { ClientCard } from './components/ClientCard';
import { ClientModal } from './components/ClientModal';
import { AnalyticsView } from './components/AnalyticsView';
import { AuthView } from './components/AuthView';

// Helper to calculate days difference
const getDaysDifference = (dateString: string): number => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const targetDate = new Date(dateString);
  targetDate.setHours(0, 0, 0, 0);
  const diffTime = targetDate.getTime() - today.getTime();
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const App: React.FC = () => {
  const [loggedUser, setLoggedUser] = useState<UserType | null>(null);
  const [clients, setClients] = useState<Client[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);
  const [activeTab, setActiveTab] = useState<'list' | 'analytics'>('list');
  const [filterStatus, setFilterStatus] = useState<'all' | 'active' | 'expiring' | 'expired'>('all');
  const [notificationPermission, setNotificationPermission] = useState<NotificationPermission>('default');

  const notifiedIds = useRef<Set<string>>(new Set());

  // Check for existing session on mount
  useEffect(() => {
    const session = localStorage.getItem('iptv_current_session');
    if (session) {
      setLoggedUser(JSON.parse(session));
    }

    if ("Notification" in window) {
      setNotificationPermission(Notification.permission);
    }
  }, []);

  // Load user-specific data when logged in
  useEffect(() => {
    if (loggedUser) {
      const storageKey = `iptv_data_user_${loggedUser.id}`;
      const saved = localStorage.getItem(storageKey);
      if (saved) {
        try {
          setClients(JSON.parse(saved));
        } catch (e) {
          console.error("Failed to parse clients", e);
        }
      } else {
        setClients([]); // Reset if new user
      }
    }
  }, [loggedUser]);

  // Save to user-specific storage
  useEffect(() => {
    if (loggedUser) {
      const storageKey = `iptv_data_user_${loggedUser.id}`;
      localStorage.setItem(storageKey, JSON.stringify(clients));

      if (Notification.permission === 'granted') {
        clients.forEach(client => {
          const days = getDaysDifference(client.renewalDate);
          if (days >= 0 && days <= 3 && !notifiedIds.current.has(client.id)) {
            const n = new Notification("Aviso de Vencimento IPTV", {
              body: `O cliente ${client.name} vence em ${days === 0 ? 'hoje' : days + ' dias'}!`,
              icon: 'https://cdn-icons-png.flaticon.com/512/5903/5903541.png',
              tag: `renewal-${client.id}`
            });
            n.onclick = () => { window.focus(); n.close(); };
            notifiedIds.current.add(client.id);
          }
        });
      }
    }
  }, [clients, loggedUser]);

  const handleLogin = (user: UserType) => {
    localStorage.setItem('iptv_current_session', JSON.stringify(user));
    setLoggedUser(user);
  };

  const handleLogout = () => {
    localStorage.removeItem('iptv_current_session');
    setLoggedUser(null);
    setClients([]);
    notifiedIds.current.clear();
  };

  const requestNotificationPermission = () => {
    if ("Notification" in window) {
      Notification.requestPermission().then(setNotificationPermission);
    }
  };

  const stats: ClientStats = useMemo(() => {
    let revenue = 0;
    let expiring = 0;
    clients.forEach(c => {
      revenue += c.price;
      const days = getDaysDifference(c.renewalDate);
      if (days >= 0 && days <= 3) expiring++;
    });
    return { totalClients: clients.length, activeRevenue: revenue, expiringSoon: expiring };
  }, [clients]);

  const counts = useMemo(() => {
    const counts = { all: clients.length, active: 0, expiring: 0, expired: 0 };
    clients.forEach(c => {
      const days = getDaysDifference(c.renewalDate);
      if (days < 0) counts.expired++;
      else if (days <= 3) counts.expiring++;
      else counts.active++;
    });
    return counts;
  }, [clients]);

  const filteredClients = useMemo(() => {
    return clients
      .filter(c => {
        const matchesSearch = c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                             c.server?.toLowerCase().includes(searchTerm.toLowerCase());
        if (!matchesSearch) return false;
        const days = getDaysDifference(c.renewalDate);
        if (filterStatus === 'active') return days > 3;
        if (filterStatus === 'expiring') return days >= 0 && days <= 3;
        if (filterStatus === 'expired') return days < 0;
        return true;
      })
      .sort((a, b) => {
        const daysA = getDaysDifference(a.renewalDate);
        const daysB = getDaysDifference(b.renewalDate);
        if (daysA < 0 && daysB < 0) return daysA - daysB;
        if (daysA < 0) return -1;
        if (daysB < 0) return 1;
        return daysA - daysB;
      });
  }, [clients, searchTerm, filterStatus]);

  if (!loggedUser) {
    return <AuthView onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 pb-20">
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-900/40">
              <Tv className="text-white" size={24} />
            </div>
            <h1 className="text-xl font-bold text-white tracking-tight hidden sm:block">IPTV Manager Pro</h1>
          </div>

          <div className="flex items-center gap-4">
             {/* User Info & Logout */}
             <div className="flex items-center gap-3 pr-4 border-r border-slate-800">
               <div className="text-right hidden sm:block">
                 <p className="text-xs text-slate-500 font-medium">Olá, {loggedUser.username}</p>
                 <button onClick={handleLogout} className="text-xs text-red-500 hover:text-red-400 font-bold flex items-center gap-1">
                   <LogOut size={12} /> Sair
                 </button>
               </div>
               <div className="bg-slate-800 p-2 rounded-full border border-slate-700">
                 <UserIcon size={18} className="text-blue-400" />
               </div>
               <button onClick={handleLogout} className="sm:hidden text-red-500 p-2">
                  <LogOut size={20} />
               </button>
             </div>

            {notificationPermission !== 'granted' && (
              <button onClick={requestNotificationPermission} className="p-2 text-amber-500 hover:bg-amber-500/10 rounded-lg transition-colors group relative">
                {notificationPermission === 'denied' ? <BellOff size={20} /> : <Bell size={20} />}
                <span className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full animate-ping"></span>
              </button>
            )}

            <button onClick={() => { setEditingClient(null); setIsModalOpen(true); }} className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition-all active:scale-95 shadow-lg shadow-blue-900/20">
              <Plus size={18} />
              <span className="hidden md:inline">Novo Cliente</span>
            </button>
          </div>
        </div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex border-t border-slate-800/50">
          <button onClick={() => setActiveTab('list')} className={`flex items-center gap-2 px-6 py-3 text-sm font-semibold transition-all border-b-2 ${activeTab === 'list' ? 'border-blue-500 text-blue-400 bg-blue-500/5' : 'border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-800/30'}`}>
            <LayoutDashboard size={18} /> Clientes
          </button>
          <button onClick={() => setActiveTab('analytics')} className={`flex items-center gap-2 px-6 py-3 text-sm font-semibold transition-all border-b-2 ${activeTab === 'analytics' ? 'border-blue-500 text-blue-400 bg-blue-500/5' : 'border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-800/30'}`}>
            <BarChart3 size={18} /> Análise e Gráficos
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {activeTab === 'list' ? (
          <>
            <StatsCards stats={stats} />
            <div className="space-y-4 mb-8">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={20} />
                <input type="text" placeholder="Buscar por nome ou servidor..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-slate-900 border border-slate-800 text-white rounded-xl pl-10 pr-4 py-3 focus:ring-2 focus:ring-blue-600 outline-none transition-all shadow-inner" />
              </div>

              <div className="flex flex-wrap gap-2 items-center bg-slate-900/40 p-1.5 rounded-xl border border-slate-800/50">
                <FilterButton active={filterStatus === 'all'} onClick={() => setFilterStatus('all')} label="Todos" count={counts.all} icon={<Filter size={14} />} color="slate" />
                <FilterButton active={filterStatus === 'active'} onClick={() => setFilterStatus('active')} label="Ativos" count={counts.active} icon={<CheckCircle2 size={14} />} color="green" />
                <FilterButton active={filterStatus === 'expiring'} onClick={() => setFilterStatus('expiring')} label="Vencendo" count={counts.expiring} icon={<Clock size={14} />} color="orange" />
                <FilterButton active={filterStatus === 'expired'} onClick={() => setFilterStatus('expired')} label="Vencidos" count={counts.expired} icon={<AlertCircle size={14} />} color="red" />
              </div>
            </div>

            {filteredClients.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in slide-in-from-bottom-4 duration-500">
                {filteredClients.map(client => (
                  <ClientCard key={client.id} client={client} daysUntilExpiration={getDaysDifference(client.renewalDate)} onDelete={(id) => { if (confirm('Excluir cliente?')) setClients(prev => prev.filter(c => c.id !== id)); }} onEdit={(c) => { setEditingClient(c); setIsModalOpen(true); }} />
                ))}
              </div>
            ) : (
              <div className="text-center py-20 bg-slate-900/50 rounded-3xl border border-slate-800 border-dashed">
                <Search size={32} className="text-slate-500 mx-auto mb-4" />
                <h3 className="text-xl font-bold text-white mb-2">Nada por aqui...</h3>
                <p className="text-slate-500">Adicione clientes para começar.</p>
              </div>
            )}
          </>
        ) : <AnalyticsView clients={clients} />}
      </main>

      <ClientModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={(c) => { if (editingClient) setClients(prev => prev.map(cl => cl.id === c.id ? c : cl)); else setClients(prev => [...prev, c]); }} editingClient={editingClient} />
    </div>
  );
};

const FilterButton: React.FC<{active: boolean, onClick: () => void, label: string, count: number, icon: any, color: string}> = ({ active, onClick, label, count, icon, color }) => {
  const colorMap: any = {
    slate: active ? 'bg-slate-700 text-white' : 'text-slate-400 hover:bg-slate-800/50',
    green: active ? 'bg-green-500 text-white' : 'text-green-500/70 hover:bg-green-500/10',
    orange: active ? 'bg-orange-500 text-white' : 'text-orange-500/70 hover:bg-orange-500/10',
    red: active ? 'bg-red-500 text-white' : 'text-red-500/70 hover:bg-red-500/10'
  };
  return (
    <button onClick={onClick} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${colorMap[color]}`}>
      {icon} <span>{label}</span>
      <span className={`px-1.5 py-0.5 rounded-md text-[10px] ${active ? 'bg-white/20' : 'bg-slate-800'}`}>{count}</span>
    </button>
  );
};

