          </button>
          <button onClick={() => setActiveTab('analytics')} className={`flex items-center gap-2 px-6 py-3 text-sm font-semibold transition-all border-b-2 ${activeTab === 'analytics' ? 'border-blue-500 text-blue-400 bg-blue-500/5' : 'border-transparent text-slate-400 hover:text-slate-200 hover:bg-slate-800/30'}`}>
            <BarChart3 size={18} /> Análise e Gráficos
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {activeTab === 'list' ? (
          <>
            <StatsCards stats={stats} />
            <div className="space-y-4 mb-8">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={20} />
                <input 
                  type="text" 
                  placeholder="Buscar por nome, telefone ou servidor..." 
                  value={searchTerm} 
                  onChange={(e) => setSearchTerm(e.target.value)} 
                  className="w-full bg-slate-900 border border-slate-800 text-white rounded-xl pl-10 pr-12 py-3 focus:ring-2 focus:ring-blue-600 outline-none transition-all shadow-inner" 
                />
                {searchTerm && (
                  <button 
                    onClick={() => setSearchTerm('')}
