                <FilterButton active={filterStatus === 'active'} onClick={() => setFilterStatus('active')} label="Ativos" count={counts.active} icon={<CheckCircle2 size={14} />} color="green" />
                <FilterButton active={filterStatus === 'expiring'} onClick={() => setFilterStatus('expiring')} label="Vencendo" count={counts.expiring} icon={<Clock size={14} />} color="orange" />
                <FilterButton active={filterStatus === 'expired'} onClick={() => setFilterStatus('expired')} label="Vencidos" count={counts.expired} icon={<AlertCircle size={14} />} color="red" />
              </div>
            </div>

            {filteredClients.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in slide-in-from-bottom-4 duration-500">
                {filteredClients.map(client => (
                  <ClientCard key={client.id} client={client} daysUntilExpiration={getDaysDifference(client.renewalDate)} onDelete={(id) => { if (confirm('Excluir cliente?')) setClients(prev => prev.filter(c => c.id !== id)); }} onEdit={(c) => { setEditingClient(c); setIsModalOpen(true); }} />
                ))}
              </div>
            ) : (
              <div className="text-center py-20 bg-slate-900/50 rounded-3xl border border-slate-800 border-dashed">
                <Search size={32} className="text-slate-500 mx-auto mb-4" />
                <h3 className="text-xl font-bold text-white mb-2">Nada por aqui...</h3>
                <p className="text-slate-500">
                  {debouncedSearchTerm ? `Nenhum resultado para "${debouncedSearchTerm}"` : 'Adicione clientes para começar.'}
                </p>
                {debouncedSearchTerm && (
                  <button 
                    onClick={() => setSearchTerm('')}
                    className="mt-4 text-blue-500 hover:underline text-sm font-medium"
                  >
                    Ver todos os clientes
                  </button>
                )}
              </div>
            )}
          </>
        ) : <AnalyticsView clients={clients} />}
      </main>

      <ClientModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={(c) => { if (editingClient) setClients(prev => prev.map(cl => cl.id === c.id ? c : cl)); else setClients(prev => [...prev, c]); }} editingClient={editingClient} />
    </div>
  );
};

const FilterButton: React.FC<{active: boolean, onClick: () => void, label: string, count: number, icon: any, color: string}> = ({ active, onClick, label, count, icon, color }) => {
  const colorMap: any = {
    slate: active ? 'bg-slate-700 text-white' : 'text-slate-400 hover:bg-slate-800/50',
    green: active ? 'bg-green-500 text-white' : 'text-green-500/70 hover:bg-green-500/10',
    orange: active ? 'bg-orange-500 text-white' : 'text-orange-500/70 hover:bg-orange-500/10',
    red: active ? 'bg-red-500 text-white' : 'text-red-500/70 hover:bg-red-500/10'
  };
  return (
    <button onClick={onClick} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${colorMap[color]}`}>
      {icon} <span>{label}</span>
      <span className={`px-1.5 py-0.5 rounded-md text-[10px] ${active ? 'bg-white/20' : 'bg-slate-800'}`}>{count}</span>
    </button>
  );
};

export default App;

import React, { useState } from 'react';
import { Client } from '../types';
import { Calendar, Smartphone, DollarSign, MessageCircle, Trash2, Edit, Wand2, Copy, Check, UserCheck, Clock, AlertCircle, StickyNote } from 'lucide-react';
import { generateRenewalMessage } from '../services/geminiService';

interface ClientCardProps {
  client: Client;
  daysUntilExpiration: number;
  onDelete: (id: string) => void;
  onEdit: (client: Client) => void;
}

export const ClientCard: React.FC<ClientCardProps> = ({ client, daysUntilExpiration, onDelete, onEdit }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedMsg, setGeneratedMsg] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  // Status Logic
  let statusColor = "border-green-500/30 bg-green-500/5 hover:shadow-green-900/20 hover:border-green-500/50";
  let badgeColor = "bg-green-500/10 text-green-400 border border-green-500/20";
  let iconColor = "text-green-500";
  let statusText = "Ativo";
  let StatusIcon = UserCheck;

  if (daysUntilExpiration < 0) {
    statusColor = "border-red-500/30 bg-red-500/5 hover:shadow-red-900/20 hover:border-red-500/50";
    badgeColor = "bg-red-500/10 text-red-400 border border-red-500/20";
    iconColor = "text-red-500";
    statusText = "Vencido";
    StatusIcon = AlertCircle;
  } else if (daysUntilExpiration <= 3) {
    statusColor = "border-orange-500/30 bg-orange-500/5 hover:shadow-orange-900/20 hover:border-orange-500/50";
    badgeColor = "bg-orange-500/10 text-orange-400 border border-orange-500/20";
    iconColor = "text-orange-400";
    statusText = "Vencendo";
    StatusIcon = Clock;
  }

  const handleGenerateMessage = async () => {
    setIsGenerating(true);
    setGeneratedMsg(null);
    const msg = await generateRenewalMessage(client);
    setGeneratedMsg(msg);
    setIsGenerating(false);
  };

  const copyToClipboard = () => {
    if (generatedMsg) {
      navigator.clipboard.writeText(generatedMsg);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const sendWhatsApp = () => {
    if (!client.phone) return;
    const cleanPhone = client.phone.replace(/\D/g, '');
    const text = generatedMsg ? encodeURIComponent(generatedMsg) : "";
    window.open(`https://wa.me/55${cleanPhone}?text=${text}`, '_blank');
  };

  return (
    <div className={`rounded-xl border p-5 transition-all hover:shadow-lg ${statusColor}`}>
      <div className="flex justify-between items-start mb-4">
        <div className="flex gap-3">
          <div className={`mt-1 p-2 rounded-lg bg-slate-900/80 border border-slate-700/50 ${iconColor}`}>
            <StatusIcon size={24} />
          </div>
          <div>
            <h3 className="text-xl font-bold text-white mb-1">{client.name}</h3>
            <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${badgeColor}`}>
              {statusText}
            </span>
          </div>
        </div>

        <div className="flex gap-2">
          <button 
            onClick={() => onEdit(client)}
            className="p-2 text-slate-400 hover:text-blue-400 hover:bg-slate-800 rounded-lg transition-colors"
            title="Editar"
          >
            <Edit size={18} />
          </button>
          <button 
            onClick={() => onDelete(client.id)}
            className="p-2 text-slate-400 hover:text-red-400 hover:bg-slate-800 rounded-lg transition-colors"
            title="Excluir"
          >
            <Trash2 size={18} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 mb-4 text-sm text-slate-300">
        <div className="flex items-center gap-2">
          <Calendar size={16} className="text-slate-500" />
          <span>Renova: {new Date(client.renewalDate).toLocaleDateString('pt-BR')}</span>
        </div>
        <div className="flex items-center gap-2">
          <DollarSign size={16} className="text-slate-500" />
          <span>R$ {client.price.toFixed(2)}</span>
        </div>
        <div className="flex items-center gap-2">
          <Smartphone size={16} className="text-slate-500" />
          <span>{client.devices} Tela(s)</span>
        </div>
        {client.server && (
           <div className="flex items-center gap-2">
           <span className="text-slate-500 font-bold text-xs">SRV</span>
           <span>{client.server}</span>
         </div>
        )}
      </div>

      {/* Observation Section */}
      {client.notes && (
        <div className="mb-4 p-3 bg-slate-900/50 border border-slate-800 rounded-lg flex gap-2">
          <StickyNote size={14} className="text-blue-500 shrink-0 mt-0.5" />
          <p className="text-xs text-slate-400 italic leading-relaxed">
            {client.notes}
          </p>
        </div>
      )}

      {/* Message Generator Section */}
      <div className="mt-4 pt-4 border-t border-slate-700/50">
        {!generatedMsg ? (
           <div className="flex gap-2">
             <button
              onClick={handleGenerateMessage}
              disabled={isGenerating}
              className="flex-1 bg-purple-600 hover:bg-purple-700 text-white py-2 px-4 rounded-lg flex items-center justify-center gap-2 text-sm font-medium transition-colors disabled:opacity-50"
             >
               {isGenerating ? (
                 <span className="animate-pulse">Criando...</span>
               ) : (
                 <>
                   <Wand2 size={16} />
                   Gerar Cobrança IA
                 </>
               )}
             </button>
              <button 
                onClick={() => {
                  const cleanPhone = client.phone.replace(/\D/g, '');
                  window.open(`https://wa.me/55${cleanPhone}`, '_blank');
                }}
                className="bg-green-600 hover:bg-green-700 text-white p-2 rounded-lg"
                title="WhatsApp Direto"
              >
                <MessageCircle size={20} />
              </button>
           </div>
        ) : (
          <div className="bg-slate-800 rounded-lg p-3 animate-in fade-in slide-in-from-top-2">
            <p className="text-slate-300 text-sm whitespace-pre-line mb-3 border-l-2 border-purple-500 pl-3">
              {generatedMsg}
            </p>
            <div className="flex gap-2">
              <button
                onClick={copyToClipboard}
                className="flex-1 bg-slate-700 hover:bg-slate-600 text-white py-1.5 rounded flex items-center justify-center gap-2 text-xs transition-colors"
              >
                {copied ? <Check size={14} /> : <Copy size={14} />}
                {copied ? "Copiado!" : "Copiar"}
              </button>
              <button
                onClick={sendWhatsApp}
                className="flex-1 bg-green-600 hover:bg-green-700 text-white py-1.5 rounded flex items-center justify-center gap-2 text-xs transition-colors"
              >
                <MessageCircle size={14} />
                Enviar WhatsApp
              </button>
              <button 
                 onClick={() => setGeneratedMsg(null)}
                 className="px-3 py-1 text-slate-400 hover:text-white text-xs"
              >
                Fechar
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Client } from '../types';
import { X, Save } from 'lucide-react';

interface ClientModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  editingClient: Client | null;
}

const emptyClient: Omit<Client, 'id'> = {
  name: '',
  phone: '',
  startDate: new Date().toISOString().split('T')[0],
  renewalDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
  price: 35.00,
  devices: 1,
  notes: '',
  server: ''
};

export const ClientModal: React.FC<ClientModalProps> = ({ isOpen, onClose, onSave, editingClient }) => {
  const [formData, setFormData] = useState<Omit<Client, 'id'>>(emptyClient);

  useEffect(() => {
    if (editingClient) {
      setFormData({
        name: editingClient.name,
        phone: editingClient.phone,
        startDate: editingClient.startDate.split('T')[0],
        renewalDate: editingClient.renewalDate.split('T')[0],
        price: editingClient.price,
        devices: editingClient.devices,
        notes: editingClient.notes || '',
        server: editingClient.server || ''
      });
    } else {
      setFormData(emptyClient);
    }
  }, [editingClient, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      id: editingClient ? editingClient.id : crypto.randomUUID(),
    });
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl w-full max-w-lg shadow-2xl overflow-hidden">
        <div className="p-6 border-b border-slate-800 flex justify-between items-center bg-slate-900">
          <h2 className="text-xl font-bold text-white">
            {editingClient ? 'Editar Cliente' : 'Novo Cliente'}
          </h2>
          <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
            <X size={24} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4 max-h-[80vh] overflow-y-auto">
          <div>
            <label className="block text-sm font-medium text-slate-400 mb-1">Nome Completo</label>
            <input
              type="text"
              required
              value={formData.name}
              onChange={e => setFormData({...formData, name: e.target.value})}
              className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 focus:border-transparent outline-none transition-all"
              placeholder="Ex: João da Silva"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-400 mb-1">WhatsApp / Telefone</label>
            <input
              type="tel"
              required
              value={formData.phone}
              onChange={e => setFormData({...formData, phone: e.target.value})}
              className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 focus:border-transparent outline-none transition-all"
              placeholder="Ex: 11999998888"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-400 mb-1">Início</label>
              <input
                type="date"
                required
                value={formData.startDate}
                onChange={e => setFormData({...formData, startDate: e.target.value})}
                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-400 mb-1">Renovação</label>
              <input
                type="date"
                required
                value={formData.renewalDate}
                onChange={e => setFormData({...formData, renewalDate: e.target.value})}
                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 outline-none"
              />
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div className="col-span-1">
              <label className="block text-sm font-medium text-slate-400 mb-1">Preço (R$)</label>
              <input
                type="number"
                step="0.01"
                required
                value={formData.price}
                onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})}
                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 outline-none"
              />
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-medium text-slate-400 mb-1">Telas</label>
              <input
                type="number"
                min="1"
                required
                value={formData.devices}
                onChange={e => setFormData({...formData, devices: parseInt(e.target.value)})}
                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 outline-none"
              />
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-medium text-slate-400 mb-1">Servidor</label>
              <input
                type="text"
                value={formData.server}
                onChange={e => setFormData({...formData, server: e.target.value})}
                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                placeholder="Ex: P2P"
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-400 mb-1">Observações Adicionais</label>
            <textarea
              value={formData.notes}
              onChange={e => setFormData({...formData, notes: e.target.value})}
              className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2.5 text-white focus:ring-2 focus:ring-blue-600 focus:border-transparent outline-none transition-all h-24 resize-none"
              placeholder="Informações extras, login, senha, etc."
