          <div className="pt-4 flex justify-end gap-3">
             <button
              type="button"
              onClick={onClose}
              className="px-4 py-2.5 rounded-lg text-slate-300 hover:bg-slate-800 transition-colors font-medium"
            >
              Cancelar
            </button>
            <button
              type="submit"
              className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-lg font-medium flex items-center gap-2 transition-colors shadow-lg shadow-blue-900/20"
            >
              <Save size={18} />
              Salvar Cliente
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Tv, User, Lock, ArrowRight, UserPlus, LogIn } from 'lucide-react';
import { User as UserType } from '../types';

interface AuthViewProps {
  onLogin: (user: UserType) => void;
}

export const AuthView: React.FC<AuthViewProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const getUsers = (): UserType[] => {
    const users = localStorage.getItem('iptv_users_registry');
    return users ? JSON.parse(users) : [];
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    const users = getUsers();

    if (isLogin) {
      const user = users.find(u => u.username === username && u.password === password);
      if (user) {
        onLogin({ id: user.id, username: user.username });
      } else {
        setError('Usuário ou senha inválidos.');
      }
    } else {
      if (users.find(u => u.username === username)) {
        setError('Este usuário já existe.');
        return;
      }
      const newUser: UserType = {
        id: crypto.randomUUID(),
        username,
        password
      };
      localStorage.setItem('iptv_users_registry', JSON.stringify([...users, newUser]));
      onLogin({ id: newUser.id, username: newUser.username });
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-6 bg-[#020617] relative overflow-hidden">
      {/* Background Decorative Elements */}
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-600/10 blur-[120px] rounded-full"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-600/10 blur-[120px] rounded-full"></div>

      <div className="w-full max-w-[420px] z-10 animate-fade-up">
        <div className="text-center mb-10">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-gradient-to-br from-indigo-500 to-blue-600 shadow-xl shadow-blue-900/20 mb-6">
            <Tv className="text-white" size={32} />
          </div>
          <h1 className="text-4xl font-extrabold text-white tracking-tight mb-2">IPTV Manager</h1>
          <p className="text-slate-400 text-lg">Gerencie sua operação com inteligência.</p>
        </div>

        <div className="glass rounded-[32px] p-8 md:p-10 shadow-2xl border border-white/5">
          <div className="flex items-center gap-3 mb-8">
            <div className="h-8 w-1 bg-indigo-500 rounded-full"></div>
            <h2 className="text-2xl font-bold text-white">
              {isLogin ? 'Bem-vindo de volta' : 'Crie sua conta'}
            </h2>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div className="space-y-1.5">
              <label className="text-sm font-semibold text-slate-400 ml-1">Usuário</label>
              <div className="relative group">
                <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-indigo-400 transition-colors">
                  <User size={18} />
                </div>
                <input
                  type="text"
                  required
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full bg-slate-950/40 border border-slate-800 rounded-2xl pl-12 pr-4 py-3.5 text-white placeholder:text-slate-600 focus:ring-2 focus:ring-indigo-500/50 focus:border-indigo-500/50 outline-none transition-all"
                  placeholder="Seu nome de usuário"
                />
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-semibold text-slate-400 ml-1">Senha</label>
              <div className="relative group">
                <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-indigo-400 transition-colors">
                  <Lock size={18} />
                </div>
                <input
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
