import React, { useState } from 'react';
import { Client } from '../types';
import { Calendar, Smartphone, DollarSign, MessageCircle, Trash2, Edit, Wand2, Copy, Check, UserCheck, Clock, AlertCircle, StickyNote, ExternalLink } from 'lucide-react';
import { generateRenewalMessage } from '../services/geminiService';

interface ClientCardProps {
  client: Client;
  daysUntilExpiration: number;
  onDelete: (id: string) => void;
  onEdit: (client: Client) => void;
}

export const ClientCard: React.FC<ClientCardProps> = ({ client, daysUntilExpiration, onDelete, onEdit }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedMsg, setGeneratedMsg] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  // Status Logic
  let statusTheme = {
    border: "border-emerald-500/20 hover:border-emerald-500/40",
    bg: "bg-emerald-500/5",
    badge: "bg-emerald-500/10 text-emerald-400",
    text: "Ativo",
    icon: UserCheck
  };

  if (daysUntilExpiration < 0) {
    statusTheme = {
      border: "border-rose-500/20 hover:border-rose-500/40",
      bg: "bg-rose-500/5",
      badge: "bg-rose-500/10 text-rose-400",
      text: "Vencido",
      icon: AlertCircle
    };
  } else if (daysUntilExpiration <= 3) {
    statusTheme = {
      border: "border-amber-500/20 hover:border-amber-500/40",
      bg: "bg-amber-500/5",
      badge: "bg-amber-500/10 text-amber-400",
      text: "Vencendo",
      icon: Clock
    };
  }

  const handleGenerateMessage = async () => {
    setIsGenerating(true);
    setGeneratedMsg(null);
    const msg = await generateRenewalMessage(client);
    setGeneratedMsg(msg);
    setIsGenerating(false);
  };

  const copyToClipboard = () => {
    if (generatedMsg) {
      navigator.clipboard.writeText(generatedMsg);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const sendWhatsApp = () => {
    if (!client.phone) return;
    const cleanPhone = client.phone.replace(/\D/g, '');
    const text = generatedMsg ? encodeURIComponent(generatedMsg) : "";
    window.open(`https://wa.me/55${cleanPhone}?text=${text}`, '_blank');
  };

  return (
    <div className={`glass rounded-3xl border ${statusTheme.border} p-6 transition-all duration-300 group hover:shadow-2xl`}>
      <div className="flex justify-between items-start mb-6">
        <div className="flex gap-4">
          <div className={`p-3 rounded-2xl ${statusTheme.bg} border border-white/5 text-white/80`}>
            <statusTheme.icon size={24} />
          </div>
          <div>
            <h3 className="text-xl font-bold text-white tracking-tight leading-tight truncate max-w-[160px]">
              {client.name}
            </h3>
            <span className={`inline-block mt-1 text-[10px] uppercase font-black px-2 py-0.5 rounded-full ${statusTheme.badge}`}>
              {statusTheme.text}
            </span>
          </div>
        </div>

        <div className="flex gap-1">
          <button 
            onClick={() => onEdit(client)}
            className="p-2 text-slate-500 hover:text-white hover:bg-white/5 rounded-xl transition-all"
            title="Editar"
          >
            <Edit size={18} />
          </button>
          <button 
            onClick={() => onDelete(client.id)}
            className="p-2 text-slate-500 hover:text-rose-400 hover:bg-rose-400/5 rounded-xl transition-all"
            title="Excluir"
          >
            <Trash2 size={18} />
          </button>
        </div>
      </div>

      <div className="space-y-3 mb-6">
        <div className="flex items-center justify-between text-sm">
          <span className="text-slate-500 font-medium flex items-center gap-2">
            <Calendar size={14} /> Expiração
          </span>
          <span className="text-slate-200 font-semibold">
            {new Date(client.renewalDate).toLocaleDateString('pt-BR')}
          </span>
        </div>
        <div className="flex items-center justify-between text-sm">
          <span className="text-slate-500 font-medium flex items-center gap-2">
            <DollarSign size={14} /> Valor
          </span>
          <span className="text-emerald-400 font-bold">
            R$ {client.price.toFixed(2)}
          </span>
        </div>
        <div className="flex items-center justify-between text-sm">
          <span className="text-slate-500 font-medium flex items-center gap-2">
            <Smartphone size={14} /> Telas
          </span>
          <span className="text-slate-200 font-semibold">{client.devices} dispositivo(s)</span>
        </div>
        {client.server && (
          <div className="flex items-center justify-between text-sm">
            <span className="text-slate-500 font-medium flex items-center gap-2">
              <ExternalLink size={14} /> Servidor
            </span>
            <span className="text-indigo-400 font-semibold px-2 py-0.5 bg-indigo-500/10 rounded-lg border border-indigo-500/20 uppercase text-[10px]">
              {client.server}
            </span>
          </div>
        )}
      </div>

      {client.notes && (
        <div className="mb-6 p-3.5 bg-slate-950/40 rounded-2xl border border-white/5 flex gap-3">
          <StickyNote size={14} className="text-indigo-500 shrink-0 mt-1" />
          <p className="text-xs text-slate-400 italic leading-relaxed line-clamp-2 hover:line-clamp-none transition-all cursor-default">
            {client.notes}
          </p>
        </div>
      )}

      <div className="pt-4 border-t border-white/5">
        {!generatedMsg ? (
           <div className="flex gap-2">
             <button
              onClick={handleGenerateMessage}
              disabled={isGenerating}
              className="flex-1 bg-gradient-to-r from-indigo-600 to-indigo-700 hover:from-indigo-500 hover:to-indigo-600 text-white py-3 px-4 rounded-2xl flex items-center justify-center gap-2 text-sm font-bold transition-all disabled:opacity-50 active:scale-[0.97]"
             >
               {isGenerating ? (
                 <span className="animate-pulse">Consultando IA...</span>
               ) : (
                 <>
                   <Wand2 size={16} />
                   Cobrança IA
                 </>
               )}
             </button>
              <button 
                onClick={() => {
                  const cleanPhone = client.phone.replace(/\D/g, '');
                  window.open(`https://wa.me/55${cleanPhone}`, '_blank');
                }}
                className="bg-emerald-600 hover:bg-emerald-500 text-white p-3 rounded-2xl transition-all active:scale-[0.97]"
                title="Abrir WhatsApp"
              >
                <MessageCircle size={20} />
              </button>
           </div>
        ) : (
          <div className="bg-slate-900/80 rounded-2xl p-4 border border-indigo-500/20 animate-in fade-in zoom-in-95">
            <p className="text-slate-300 text-xs whitespace-pre-line mb-4 border-l-2 border-indigo-500 pl-3 italic">
              {generatedMsg}
            </p>
            <div className="flex flex-wrap gap-2">
              <button
                onClick={copyToClipboard}
                className="flex-1 bg-white/10 hover:bg-white/20 text-white py-2 rounded-xl flex items-center justify-center gap-2 text-[11px] font-bold transition-all"
              >
                {copied ? <Check size={14} className="text-emerald-400" /> : <Copy size={14} />}
                {copied ? "Pronto!" : "Copiar"}
              </button>
              <button
                onClick={sendWhatsApp}
                className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white py-2 rounded-xl flex items-center justify-center gap-2 text-[11px] font-bold transition-all"
              >
                <MessageCircle size={14} />
                Enviar
              </button>
              <button 
                 onClick={() => setGeneratedMsg(null)}
                 className="w-full mt-2 text-slate-500 hover:text-white text-[10px] font-bold uppercase tracking-widest text-center"
              >
                Cancelar
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Client, ClientStats, User as UserType } from './types';
import { Plus, Search, Tv, Users, LayoutDashboard, BarChart3, CheckCircle2, Clock, AlertCircle, Filter, Bell, BellOff, LogOut, User as UserIcon, X } from 'lucide-react';
import { StatsCards } from './components/StatsCards';
import { ClientCard } from './components/ClientCard';
import { ClientModal } from './components/ClientModal';
import { AnalyticsView } from './components/AnalyticsView';
import { AuthView } from './components/AuthView';

const getDaysDifference = (dateString: string): number => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const targetDate = new Date(dateString);
  targetDate.setHours(0, 0, 0, 0);
  const diffTime = targetDate.getTime() - today.getTime();
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const App: React.FC = () => {
  const [loggedUser, setLoggedUser] = useState<UserType | null>(null);
  const [clients, setClients] = useState<Client[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);
  const [activeTab, setActiveTab] = useState<'list' | 'analytics'>('list');
  const [filterStatus, setFilterStatus] = useState<'all' | 'active' | 'expiring' | 'expired'>('all');
  const [notificationPermission, setNotificationPermission] = useState<NotificationPermission>('default');

  const notifiedIds = useRef<Set<string>>(new Set());

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearchTerm(searchTerm);
    }, 300);
    return () => clearTimeout(handler);
  }, [searchTerm]);

  useEffect(() => {
    const session = localStorage.getItem('iptv_current_session');
    if (session) setLoggedUser(JSON.parse(session));
    if ("Notification" in window) setNotificationPermission(Notification.permission);
  }, []);

  useEffect(() => {
    if (loggedUser) {
      const storageKey = `iptv_data_user_${loggedUser.id}`;
      const saved = localStorage.getItem(storageKey);
      if (saved) {
        try { setClients(JSON.parse(saved)); } 
        catch (e) { console.error(e); }
      } else {
        setClients([]); 
      }
    }
  }, [loggedUser]);

  useEffect(() => {
    if (loggedUser) {
      const storageKey = `iptv_data_user_${loggedUser.id}`;
      localStorage.setItem(storageKey, JSON.stringify(clients));

      if (Notification.permission === 'granted') {
        clients.forEach(client => {
          const days = getDaysDifference(client.renewalDate);
          if (days >= 0 && days <= 3 && !notifiedIds.current.has(client.id)) {
            const n = new Notification("IPTV Manager: Renovação", {
              body: `O cliente ${client.name} vence em ${days === 0 ? 'hoje' : days + ' dias'}!`,
              icon: 'https://cdn-icons-png.flaticon.com/512/5903/5903541.png',
              tag: `renewal-${client.id}`
            });
            notifiedIds.current.add(client.id);
          }
        });
      }
    }
  }, [clients, loggedUser]);

  const stats: ClientStats = useMemo(() => {
    let revenue = 0;
    let expiring = 0;
    clients.forEach(c => {
      revenue += c.price;
      const days = getDaysDifference(c.renewalDate);
      if (days >= 0 && days <= 3) expiring++;
    });
    return { totalClients: clients.length, activeRevenue: revenue, expiringSoon: expiring };
  }, [clients]);

  const counts = useMemo(() => {
    const counts = { all: clients.length, active: 0, expiring: 0, expired: 0 };
    clients.forEach(c => {
      const days = getDaysDifference(c.renewalDate);
      if (days < 0) counts.expired++;
      else if (days <= 3) counts.expiring++;
      else counts.active++;
    });
    return counts;
  }, [clients]);

  const filteredClients = useMemo(() => {
    const query = debouncedSearchTerm.toLowerCase();
    return clients
      .filter(c => {
        if (query) {
          const matchesSearch = c.name.toLowerCase().includes(query) || 
                               c.server?.toLowerCase().includes(query) ||
                               c.phone.includes(query);
          if (!matchesSearch) return false;
        }
        const days = getDaysDifference(c.renewalDate);
        if (filterStatus === 'active') return days > 3;
        if (filterStatus === 'expiring') return days >= 0 && days <= 3;
        if (filterStatus === 'expired') return days < 0;
        return true;
      })
      .sort((a, b) => getDaysDifference(a.renewalDate) - getDaysDifference(b.renewalDate));
  }, [clients, debouncedSearchTerm, filterStatus]);

  if (!loggedUser) return <AuthView onLogin={user => {
    localStorage.setItem('iptv_current_session', JSON.stringify(user));
    setLoggedUser(user);
  }} />;

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200">
      {/* Dynamic Header */}
      <header className="sticky top-0 z-40 glass border-b border-white/5">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-900/40">
              <Tv className="text-white" size={20} />
            </div>
            <div>
              <h1 className="text-lg font-black tracking-tighter text-white">MANAGER PRO</h1>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.2em]">SaaS Dashboard</p>
            </div>
          </div>

          <div className="flex items-center gap-6">
             <div className="hidden md:flex items-center gap-3 pr-6 border-r border-white/5">
               <div className="text-right">
                 <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Usuário Logado</p>
                 <p className="text-sm font-bold text-white">{loggedUser.username}</p>
               </div>
               <div className="w-10 h-10 rounded-full bg-slate-800 border border-white/10 flex items-center justify-center">
                 <UserIcon size={18} className="text-indigo-400" />
               </div>
             </div>

            <div className="flex gap-2">
              <button onClick={() => { localStorage.removeItem('iptv_current_session'); setLoggedUser(null); }} className="p-3 text-slate-400 hover:text-rose-400 transition-colors">
                <LogOut size={22} />
              </button>
              <button onClick={() => { setEditingClient(null); setIsModalOpen(true); }} className="bg-indigo-600 hover:bg-indigo-500 text-white px-5 py-2.5 rounded-2xl text-sm font-black flex items-center gap-2 transition-all active:scale-95 shadow-xl shadow-indigo-900/20">
                <Plus size={18} />
                <span className="hidden sm:inline">NOVO CLIENTE</span>
              </button>
            </div>
          </div>
        </div>

        {/* Tab Switcher */}
        <div className="max-w-7xl mx-auto px-6 flex">
          <button onClick={() => setActiveTab('list')} className={`flex items-center gap-2 px-8 py-4 text-xs font-black uppercase tracking-widest transition-all relative ${activeTab === 'list' ? 'text-white' : 'text-slate-500 hover:text-slate-300'}`}>
            <LayoutDashboard size={14} /> Painel Principal
            {activeTab === 'list' && <div className="absolute bottom-0 left-0 w-full h-1 bg-indigo-500 rounded-full shadow-[0_-4px_12px_rgba(99,102,241,0.6)]"></div>}
          </button>
          <button onClick={() => setActiveTab('analytics')} className={`flex items-center gap-2 px-8 py-4 text-xs font-black uppercase tracking-widest transition-all relative ${activeTab === 'analytics' ? 'text-white' : 'text-slate-500 hover:text-slate-300'}`}>
            <BarChart3 size={14} /> Analytics
            {activeTab === 'analytics' && <div className="absolute bottom-0 left-0 w-full h-1 bg-indigo-500 rounded-full shadow-[0_-4px_12px_rgba(99,102,241,0.6)]"></div>}
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-10 animate-fade-up">
        {activeTab === 'list' ? (
          <>
            <StatsCards stats={stats} />

            <div className="space-y-6 mb-12">
              <div className="relative group">
                <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-indigo-500 transition-colors" size={20} />
                <input 
                  type="text" 
                  placeholder="Pesquisar por nome, servidor ou telefone..." 
                  value={searchTerm} 
                  onChange={(e) => setSearchTerm(e.target.value)} 
                  className="w-full bg-slate-900/50 border border-white/5 text-white rounded-[24px] pl-14 pr-16 py-5 focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500/30 outline-none transition-all text-lg font-medium shadow-inner" 
                />
                {searchTerm && (
                  <button onClick={() => setSearchTerm('')} className="absolute right-5 top-1/2 -translate-y-1/2 bg-white/5 hover:bg-white/10 p-2 rounded-xl transition-all">
                    <X size={16} className="text-slate-400" />
                  </button>
                )}
              </div>

              <div className="flex flex-wrap gap-3 items-center p-2 rounded-[24px] bg-slate-900/40 border border-white/5">
                <FilterTab active={filterStatus === 'all'} onClick={() => setFilterStatus('all')} label="Todos" count={counts.all} color="indigo" />
                <FilterTab active={filterStatus === 'active'} onClick={() => setFilterStatus('active')} label="Ativos" count={counts.active} color="emerald" />
                <FilterTab active={filterStatus === 'expiring'} onClick={() => setFilterStatus('expiring')} label="Vencendo" count={counts.expiring} color="amber" />
                <FilterTab active={filterStatus === 'expired'} onClick={() => setFilterStatus('expired')} label="Vencidos" count={counts.expired} color="rose" />
              </div>
            </div>

            {filteredClients.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {filteredClients.map(client => (
                  <ClientCard 
                    key={client.id} 
                    client={client} 
                    daysUntilExpiration={getDaysDifference(client.renewalDate)} 
                    onDelete={(id) => { if (confirm('Excluir este cliente permanentemente?')) setClients(prev => prev.filter(c => c.id !== id)); }} 
                    onEdit={(c) => { setEditingClient(c); setIsModalOpen(true); }} 
                  />
                ))}
              </div>
            ) : (
              <div className="text-center py-24 glass rounded-[40px] border-dashed border-2 border-white/5">
                <div className="w-20 h-20 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-6">
                  <Search size={32} className="text-slate-500" />
                </div>
                <h3 className="text-2xl font-bold text-white mb-3">Nenhum registro encontrado</h3>
                <p className="text-slate-500 max-w-sm mx-auto">Tente ajustar seus filtros ou adicione um novo cliente para começar sua gestão.</p>
              </div>
            )}
          </>
        ) : <AnalyticsView clients={clients} />}
      </main>

      <ClientModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={(c) => { if (editingClient) setClients(prev => prev.map(cl => cl.id === c.id ? c : cl)); else setClients(prev => [...prev, c]); }} 
        editingClient={editingClient} 
      />
    </div>
  );
};

const FilterTab: React.FC<{active: boolean, onClick: () => void, label: string, count: number, color: string}> = ({ active, onClick, label, count, color }) => {
  const colorMap: any = {
    indigo: active ? 'bg-indigo-600 text-white' : 'text-slate-500 hover:bg-white/5',
    emerald: active ? 'bg-emerald-600 text-white' : 'text-slate-500 hover:bg-white/5',
    amber: active ? 'bg-amber-600 text-white' : 'text-slate-500 hover:bg-white/5',
    rose: active ? 'bg-rose-600 text-white' : 'text-slate-500 hover:bg-white/5'
  };
  return (
    <button onClick={onClick} className={`flex items-center gap-3 px-6 py-3 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all ${colorMap[color]}`}>
      {label}
      <span className={`px-2 py-0.5 rounded-lg ${active ? 'bg-black/20' : 'bg-slate-800'}`}>{count}</span>
    </button>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Client } from '../types';
import { X, Save, User, Smartphone, Server, FileText, Calendar, CreditCard } from 'lucide-react';

interface ClientModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  editingClient: Client | null;
}

const emptyClient: Omit<Client, 'id'> = {
  name: '',
  phone: '',
  startDate: new Date().toISOString().split('T')[0],
  renewalDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
  price: 35.00,
  devices: 1,
  notes: '',
  server: ''
};

export const ClientModal: React.FC<ClientModalProps> = ({ isOpen, onClose, onSave, editingClient }) => {
  const [formData, setFormData] = useState<Omit<Client, 'id'>>(emptyClient);

  useEffect(() => {
    if (editingClient) {
      setFormData({
        name: editingClient.name,
        phone: editingClient.phone,
        startDate: editingClient.startDate.split('T')[0],
        renewalDate: editingClient.renewalDate.split('T')[0],
        price: editingClient.price,
        devices: editingClient.devices,
        notes: editingClient.notes || '',
        server: editingClient.server || ''
      });
    } else {
      setFormData(emptyClient);
    }
  }, [editingClient, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      id: editingClient ? editingClient.id : crypto.randomUUID(),
    });
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-xl animate-in fade-in duration-300">
      <div className="glass border-white/10 rounded-[40px] w-full max-w-2xl shadow-3xl overflow-hidden animate-in zoom-in-95 duration-300">
        <div className="px-8 py-6 border-b border-white/5 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-500/20 rounded-xl flex items-center justify-center">
              <User className="text-indigo-400" size={20} />
            </div>
            <h2 className="text-2xl font-extrabold text-white tracking-tight">
              {editingClient ? 'Editar Cliente' : 'Novo Registro'}
            </h2>
          </div>
          <button onClick={onClose} className="w-10 h-10 flex items-center justify-center text-slate-500 hover:text-white hover:bg-white/5 rounded-full transition-all">
            <X size={24} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-8 max-h-[75vh] overflow-y-auto">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">Nome do Cliente</label>
              <div className="relative">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" size={16} />
                <input
                  type="text"
                  required
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  className="w-full bg-slate-950/40 border border-white/5 rounded-2xl pl-12 pr-4 py-4 text-white focus:ring-2 focus:ring-indigo-500/30 outline-none transition-all font-medium"
                  placeholder="Nome completo"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">WhatsApp</label>
              <div className="relative">
                <Smartphone className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" size={16} />
                <input
                  type="tel"
                  required
                  value={formData.phone}
                  onChange={e => setFormData({...formData, phone: e.target.value})}
                  className="w-full bg-slate-950/40 border border-white/5 rounded-2xl pl-12 pr-4 py-4 text-white focus:ring-2 focus:ring-indigo-500/30 outline-none transition-all font-medium"
                  placeholder="DDD + Número"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">Data Início</label>
              <div className="relative">
                <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" size={16} />
                <input
                  type="date"
                  required
                  value={formData.startDate}
                  onChange={e => setFormData({...formData, startDate: e.target.value})}
                  className="w-full bg-slate-950/40 border border-white/5 rounded-2xl pl-12 pr-4 py-4 text-white focus:ring-2 focus:ring-indigo-500/30 outline-none"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1 text-indigo-400">Próxima Renovação</label>
              <div className="relative">
                <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-indigo-400/50" size={16} />
                <input
                  type="date"
                  required
                  value={formData.renewalDate}
                  onChange={e => setFormData({...formData, renewalDate: e.target.value})}
                  className="w-full bg-slate-950/40 border border-indigo-500/20 rounded-2xl pl-12 pr-4 py-4 text-indigo-400 focus:ring-2 focus:ring-indigo-500/30 outline-none font-bold"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">Preço (R$)</label>
              <div className="relative">
                <CreditCard className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" size={16} />
                <input
                  type="number"
                  step="0.01"
                  required
                  value={formData.price}
                  onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})}
                  className="w-full bg-slate-950/40 border border-white/5 rounded-2xl pl-12 pr-4 py-4 text-white focus:ring-2 focus:ring-indigo-500/30 outline-none font-bold"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">Servidor / Painel</label>
              <div className="relative">
                <Server className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" size={16} />
                <input
                  type="text"
                  value={formData.server}
                  onChange={e => setFormData({...formData, server: e.target.value})}
                  className="w-full bg-slate-950/40 border border-white/5 rounded-2xl pl-12 pr-4 py-4 text-white focus:ring-2 focus:ring-indigo-500/30 outline-none transition-all uppercase placeholder:normal-case font-bold"
                  placeholder="Ex: P2P, Gold, Master"
                />
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">Observações Privadas</label>
            <div className="relative">
              <FileText className="absolute left-4 top-4 text-slate-600" size={16} />
              <textarea
                value={formData.notes}
                onChange={e => setFormData({...formData, notes: e.target.value})}
                className="w-full bg-slate-950/40 border border-white/5 rounded-3xl pl-12 pr-4 py-4 text-white focus:ring-2 focus:ring-indigo-500/30 outline-none transition-all h-32 resize-none text-sm font-medium"
                placeholder="Login, senha, detalhes do plano..."
              />
            </div>
          </div>

          <div className="pt-8 flex justify-end gap-4">
             <button
              type="button"
              onClick={onClose}
              className="px-8 py-4 rounded-2xl text-slate-400 hover:text-white hover:bg-white/5 transition-all text-xs font-black uppercase tracking-widest"
            >
              Cancelar
            </button>
            <button
