import { initializeApp } from "firebase/app";
import { 
  getAuth, 
  GoogleAuthProvider, 
  signInWithPopup as firebaseSignInWithPopup,
  signOut as firebaseSignOut,
  onAuthStateChanged as firebaseOnAuthStateChanged
} from "firebase/auth";

// ============================================================
// CONFIGURAÇÃO DO FIREBASE
// Se mantiver as chaves de exemplo, o app entrará em MODO DEMO.
// Para usar o Firebase real, substitua pelo seu config do Console.
// ============================================================

const firebaseConfig = {
  apiKey: "AIzaSy...", 
  authDomain: "seu-projeto.firebaseapp.com",
  projectId: "seu-projeto",
  storageBucket: "seu-projeto.appspot.com",
  messagingSenderId: "123456...",
  appId: "1:123456..."
};

// Verifica se está usando a configuração padrão/inválida
const isDemoMode = firebaseConfig.apiKey === "AIzaSy..." || firebaseConfig.apiKey.includes("SUA_API_KEY");

let auth: any;
let googleProvider: any;
let signInWithPopup: any;
let signOut: any;
let onAuthStateChanged: any;

if (!isDemoMode) {
  // --- MODO REAL ---
  const app = initializeApp(firebaseConfig);
  auth = getAuth(app);
  googleProvider = new GoogleAuthProvider();
  signInWithPopup = firebaseSignInWithPopup;
  signOut = firebaseSignOut;
  onAuthStateChanged = firebaseOnAuthStateChanged;
} else {
  // --- MODO DEMO (MOCK) ---
  console.warn("⚠️ MODO DEMO ATIVADO: Autenticação simulada (Sem Firebase)");

  // Usuário Fictício
  const mockUser = {
    uid: "demo-user-123",
    displayName: "Admin Demo",
    email: "admin@iptvmanager.com",
    photoURL: "https://ui-avatars.com/api/?name=Admin+Demo&background=4f46e5&color=fff&rounded=true",
    emailVerified: true
  };

  // Estado local simples
  let currentUser: any = localStorage.getItem('demo_auth_user') ? mockUser : null;
  const observers: any[] = [];

  auth = { currentUser };
  googleProvider = {}; // Mock provider

  signInWithPopup = async () => {
    return new Promise((resolve) => {
      setTimeout(() => {
        currentUser = mockUser;
        localStorage.setItem('demo_auth_user', 'true');
        observers.forEach(cb => cb(currentUser));
        resolve({ user: currentUser });
      }, 800); // Simula delay de rede
    });
  };

  signOut = async () => {
    return new Promise((resolve) => {
      setTimeout(() => {
        currentUser = null;
        localStorage.removeItem('demo_auth_user');
        observers.forEach(cb => cb(null));
        resolve(void 0);
      }, 400);
    });
  };

  onAuthStateChanged = (_auth: any, callback: any) => {
    observers.push(callback);
    // Dispara estado inicial
    setTimeout(() => callback(currentUser), 100);
    // Retorna função de unsubscribe
    return () => {
      const idx = observers.indexOf(callback);
      if (idx > -1) observers.splice(idx, 1);
    };
  };
}

export { auth, googleProvider, signInWithPopup, signOut, onAuthStateChanged };

import React, { useState, useEffect, useMemo } from 'react';
import { Client, ClientStats, User as UserType } from './types';
import { Plus, Search, Tv, LayoutDashboard, BarChart3, LogOut, X } from 'lucide-react';
import { StatsCards } from './components/StatsCards';
import { ClientCard } from './components/ClientCard';
import { ClientModal } from './components/ClientModal';
import { AnalyticsView } from './components/AnalyticsView';
import { AuthView } from './components/AuthView';
import { auth, onAuthStateChanged, signOut } from './services/firebase';

const getDaysDifference = (dateString: string): number => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const targetDate = new Date(dateString);
  targetDate.setHours(0, 0, 0, 0);
  const diffTime = targetDate.getTime() - today.getTime();
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const App: React.FC = () => {
  const [loggedUser, setLoggedUser] = useState<UserType | null>(null);
  const [loadingAuth, setLoadingAuth] = useState(true);
  const [clients, setClients] = useState<Client[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);
  const [activeTab, setActiveTab] = useState<'list' | 'analytics'>('list');
  const [filterStatus, setFilterStatus] = useState<'all' | 'active' | 'expiring' | 'expired'>('all');

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearchTerm(searchTerm);
    }, 300);
    return () => clearTimeout(handler);
  }, [searchTerm]);

  // Monitoramento de Autenticação (Observer do Firebase/Mock)
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user: any) => {
      if (user) {
        // Usuário Logado
        setLoggedUser({
          id: user.uid,
          username: user.displayName || 'Usuário',
          email: user.email || '',
          avatar: user.photoURL || undefined
        });
      } else {
        // Usuário Deslogado
        setLoggedUser(null);
      }
      setLoadingAuth(false);
    });

    return () => unsubscribe();
  }, []);

  // Carregar dados específicos do usuário logado
  useEffect(() => {
    if (loggedUser) {
      const storageKey = `iptv_data_user_${loggedUser.id}`;
      const saved = localStorage.getItem(storageKey);
      if (saved) {
        try { setClients(JSON.parse(saved)); } 
        catch (e) { console.error(e); }
      } else {
        setClients([]); 
      }
    }
  }, [loggedUser]);

  // Salvar dados
  useEffect(() => {
    if (loggedUser) {
      const storageKey = `iptv_data_user_${loggedUser.id}`;
      localStorage.setItem(storageKey, JSON.stringify(clients));
    }
  }, [clients, loggedUser]);

  const handleLogout = async () => {
    try {
      await signOut(auth);
      setLoggedUser(null);
    } catch (error) {
      console.error("Erro ao sair:", error);
    }
  };

  const handleRenewClient = (id: string) => {
    setClients(prev => prev.map(client => {
      if (client.id !== id) return client;

      const today = new Date();
      const currentRenewal = new Date(client.renewalDate);
      let newDate = new Date();

      if (currentRenewal < today) {
        newDate = new Date(today);
      } else {
        newDate = new Date(currentRenewal);
      }

      newDate.setDate(newDate.getDate() + 30);

      return {
        ...client,
        renewalDate: newDate.toISOString()
      };
    }));
  };

  const stats: ClientStats = useMemo(() => {
    let revenue = 0;
    let expiring = 0;
    clients.forEach(c => {
      revenue += c.price;
      const days = getDaysDifference(c.renewalDate);
      if (days >= 0 && days <= 3) expiring++;
    });
    return { totalClients: clients.length, activeRevenue: revenue, expiringSoon: expiring };
  }, [clients]);

  const counts = useMemo(() => {
    const counts = { all: clients.length, active: 0, expiring: 0, expired: 0 };
    clients.forEach(c => {
      const days = getDaysDifference(c.renewalDate);
      if (days < 0) counts.expired++;
      else if (days <= 3) counts.expiring++;
      else counts.active++;
    });
    return counts;
  }, [clients]);

  const filteredClients = useMemo(() => {
    const query = debouncedSearchTerm.toLowerCase();
    return clients
      .filter(c => {
        if (query) {
          const matchesSearch = c.name.toLowerCase().includes(query) || 
                               c.server?.toLowerCase().includes(query) ||
                               c.phone.includes(query) ||
                               c.macAddress?.toLowerCase().includes(query);
          if (!matchesSearch) return false;
        }
        const days = getDaysDifference(c.renewalDate);
        if (filterStatus === 'active') return days > 3;
        if (filterStatus === 'expiring') return days >= 0 && days <= 3;
        if (filterStatus === 'expired') return days < 0;
        return true;
      })
      .sort((a, b) => getDaysDifference(a.renewalDate) - getDaysDifference(b.renewalDate));
  }, [clients, debouncedSearchTerm, filterStatus]);

  if (loadingAuth) {
    return <div className="min-h-screen bg-[#020617] flex items-center justify-center">
      <div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
    </div>;
  }

  // Div #tela-login (Conceitualmente, renderizada quando !loggedUser)
  if (!loggedUser) return <AuthView />;

  // Div #conteudo-sistema (Renderizada quando loggedUser é true)
  return (
    <div id="conteudo-sistema" className="min-h-screen bg-[#020617] text-slate-200 pb-safe">
      {/* iOS Optimized Header with Google User Info */}
      <header className="sticky top-0 z-40 glass border-b border-white/5 pt-[env(safe-area-inset-top)]">
        <div className="max-w-7xl mx-auto px-4 h-16 md:h-20 flex items-center justify-between">
